using Microsoft.EntityFrameworkCore;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace Society.Api;
public record ManualMemberWrite(string FullName,string? Number,Guid ChapterId,Guid CategoryId,string Status,DateOnly JoinedOn,DateOnly ValidFrom,DateOnly? ValidThrough,string Profile,int Revision,string Reason,bool ReclassifyConfirmed=false,bool AllowEmailClaim=false);
public record ManualMemberAction(int Revision,string Reason);
public static class PlatformMemberAdmin {
 public static async Task Require(Access a){if(!await a.Platform())throw new AccessDeniedException();}
 static readonly TimeZoneInfo India=TimeZoneInfo.FindSystemTimeZoneById("Asia/Kolkata");
 public static DateOnly Date(DateTimeOffset value)=>DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(value,India).DateTime);
 static DateTimeOffset Start(DateOnly day)=>new(TimeZoneInfo.ConvertTimeToUtc(day.ToDateTime(TimeOnly.MinValue),India));
 static void Reason(string reason){if(string.IsNullOrWhiteSpace(reason)||reason.Trim().Length<5||reason.Length>1000)throw new DomainException("Enter an administration reason of 5–1,000 characters");}
 static async Task Tenant(Guid tenant,AppDb db){if(!await db.Tenants.AnyAsync(t=>t.Id==tenant))throw new DomainException("Choose an existing society");}
 static object Snapshot(Membership m,Person p)=>new{fullName=p.FullName,m.Number,m.ChapterId,m.CategoryId,m.Status,m.JoinedAt,m.EffectiveFrom,m.EndsAt,m.PendingPayment,profile=MembershipService.Json(m.Profile)};
 public static void Map(RouteGroupBuilder api){api.MapGet("/platform/membership/societies",async(AppDb db,Access a)=>{await Require(a);return await db.Tenants.OrderBy(t=>t.Name).Select(t=>new{t.Id,t.Name,t.Status,t.Profile}).ToListAsync();}).RequireAuthorization();var t=api.MapGroup("/platform/membership/{tenant:guid}").RequireAuthorization();
 t.MapGet("/setup",async(Guid tenant,AppDb db,Access a)=>{await Require(a);await Tenant(tenant,db);return Results.Ok(new{categories=await db.MembershipCategories.Where(c=>c.TenantId==tenant).OrderBy(c=>c.Name).Select(c=>new{c.Id,c.Name,c.Kind,c.Active}).ToListAsync(),chapters=await db.Units.Where(u=>u.TenantId==tenant&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")).OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name,u.Status}).ToListAsync(),statuses=MembershipService.Statuses});});
 t.MapGet("/duplicates",async(Guid tenant,string? name,string? email,string? number,string? kind,AppDb db,Access a)=>{await Require(a);var nm=(name??"").Trim().ToLower();var em=(email??"").Trim().ToLower();var num=(number??"").Trim().ToLower();var emails=db.Memberships.FromSqlInterpolated($"SELECT * FROM \"Memberships\" WHERE \"TenantId\"={tenant} AND lower(\"Profile\"->>'email')={em}").Select(m=>m.Id);var q=MembershipIdentity.Filter(db,db.Memberships.Where(m=>m.TenantId==tenant),kind);return await(from m in q join p in db.Persons on m.PersonId equals p.Id where (nm.Length>=3&&p.SearchName==nm)||(em!=""&&emails.Contains(m.Id))||(num!=""&&m.Number.ToLower()==num) select new{m.Id,m.Number,p.FullName}).Take(10).ToListAsync();});
 t.MapGet("/members/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a)=>{await Require(a);var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id);if(m==null)return Results.NotFound();var p=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);var kind=await db.MembershipCategories.Where(c=>c.TenantId==tenant&&c.Id==m.CategoryId).Select(c=>c.Kind).SingleAsync();return Results.Ok(new{member=Snapshot(m,p),m.Revision,kind,joinedOn=Date(m.JoinedAt),validFrom=Date(m.EffectiveFrom),validThrough=m.EndsAt==null?(DateOnly?)null:Date(m.EndsAt.Value.AddTicks(-1)),profile=MembershipService.Json(m.Profile),archived=MembershipService.Json(m.Profile)["adminArchived"]?.GetValue<bool>()==true});});
 t.MapPost("/members",async(Guid tenant,ManualMemberWrite r,AppDb db,Access a,MembershipService s)=>await Save(tenant,null,r,db,a,s));
 t.MapPut("/members/{id:guid}",async(Guid tenant,Guid id,ManualMemberWrite r,AppDb db,Access a,MembershipService s)=>await Save(tenant,id,r,db,a,s));
 t.MapDelete("/members/{id:guid}",async(Guid tenant,Guid id,[Microsoft.AspNetCore.Mvc.FromBody] ManualMemberAction r,AppDb db,Access a,MembershipService s)=>{await Require(a);var revision=r.Revision;var reason=r.Reason;Reason(reason);await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id);if(m==null)return Results.NotFound();if(m.Revision!=revision)return Results.Conflict(new{title="Membership changed. Refresh before deleting."});var p=MembershipService.Json(m.Profile);if(p["adminArchived"]?.GetValue<bool>()==true)throw new DomainException("Membership is already archived");var person=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);var before=Snapshot(m,person);p["adminArchived"]=true;p["adminArchivePreviousStatus"]=m.Status;p["adminArchivedAt"]=DateTimeOffset.UtcNow.ToString("O");m.Profile=p.ToJsonString();m.Status="Closed";m.Revision++;await s.RevokeOfficers(m,a.UserId);await s.SyncDirectoryTerm(m);s.History(m,a.UserId,"platform.membership.archived",new{reason,before,after=Snapshot(m,person)});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 t.MapPost("/members/{id:guid}/restore",async(Guid tenant,Guid id,ManualMemberAction r,AppDb db,Access a,MembershipService s)=>{await Require(a);Reason(r.Reason);await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id);if(m==null)return Results.NotFound();if(m.Revision!=r.Revision)return Results.Conflict(new{title="Membership changed. Refresh before restoring."});var p=MembershipService.Json(m.Profile);if(p["adminArchived"]?.GetValue<bool>()!=true)throw new DomainException("Only archived memberships can be restored");var previous=p["adminArchivePreviousStatus"]?.ToString();m.Status=previous!=null&&MembershipService.Statuses.Contains(previous)?previous:"Inactive";p.Remove("adminArchived");p.Remove("adminArchivePreviousStatus");p.Remove("adminArchivedAt");m.Profile=p.ToJsonString();m.Revision++;await s.SyncDirectoryTerm(m);s.History(m,a.UserId,"platform.membership.restored",new{r.Reason,m.Status});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 }
 static async Task<IResult> Save(Guid tenant,Guid? id,ManualMemberWrite r,AppDb db,Access a,MembershipService s){
  await Require(a);await Tenant(tenant,db);Reason(r.Reason);if(string.IsNullOrWhiteSpace(r.FullName)||r.FullName.Trim().Length>160)throw new DomainException("Enter a holder name of up to 160 characters");if(!MembershipService.Statuses.Contains(r.Status))throw new DomainException("Choose a valid membership status");if(r.JoinedOn.Year<1900||r.ValidFrom.Year<1900||r.ValidFrom.Year>9998||r.JoinedOn.Year>9998||r.ValidThrough?.Year>9998)throw new DomainException("Choose dates between 1900 and 9998, or no expiry");if(r.ValidThrough!=null&&r.ValidThrough<r.ValidFrom)throw new DomainException("Expiry must be on or after the valid-from date");
  await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var m=id==null?null:await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id);if(id!=null&&m==null)return Results.NotFound();if(m!=null&&m.Revision!=r.Revision)return Results.Conflict(new{title="Membership changed. Refresh before saving."});
  var chapter=await db.Units.SingleOrDefaultAsync(u=>u.TenantId==tenant&&u.Id==r.ChapterId&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter"))??throw new DomainException("Choose a chapter in this society");if(chapter.Status=="Archived"&&(m==null||m.ChapterId!=chapter.Id))throw new DomainException("Restore the chapter before assigning a membership to it");var category=await db.MembershipCategories.SingleOrDefaultAsync(c=>c.TenantId==tenant&&c.Id==r.CategoryId)??throw new DomainException("Choose a membership type in this society");if(!category.Active&&(m==null||m.CategoryId!=category.Id))throw new DomainException("Activate this membership type before assigning it");
  var number=string.IsNullOrWhiteSpace(r.Number)?m?.Number??"M-"+Guid.NewGuid().ToString("N")[..16].ToUpperInvariant():r.Number.Trim().ToUpperInvariant();if(!Regex.IsMatch(number,"^[A-Z0-9_-]{1,40}$"))throw new DomainException("Membership ID must use up to 40 letters, digits, underscores or hyphens");if(await db.Memberships.AnyAsync(x=>x.TenantId==tenant&&x.Id!=id&&x.Number==number))return Results.Conflict(new{title="That membership ID is already in use"});
  var profile=MembershipService.Json(r.Profile);MembershipService.ValidateProfile(r.Profile);foreach(var key in new[]{"adminArchived","adminArchivePreviousStatus","adminArchivedAt"})profile.Remove(key);
  Person person;object? before=null;var reclassified=false;
  if(m==null){person=new Person();db.Persons.Add(person);m=new Membership{TenantId=tenant,PersonId=person.Id,Privacy=MembershipService.DefaultPrivacy};db.Memberships.Add(m);}else{person=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);before=Snapshot(m,person);if(MembershipService.Json(m.Profile)["adminArchived"]?.GetValue<bool>()==true)throw new DomainException("Restore the archived membership before editing");var oldKind=await db.MembershipCategories.Where(c=>c.Id==m.CategoryId).Select(c=>c.Kind).SingleAsync();if(oldKind!=category.Kind){if(!r.ReclassifyConfirmed)throw new DomainException("Confirm the change between a person and an organization");var linked=person.UserId!=null||await db.Memberships.AnyAsync(x=>x.PersonId==person.Id&&x.Id!=m.Id)||await db.MembershipHistories.AnyAsync(h=>h.MembershipId==m.Id&&(h.Action=="membership.import.approved"||h.Action=="membership.manual.claim.approved"))||await db.OfficerAppointments.AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<InstitutionChapter>().AnyAsync(l=>l.MembershipId==m.Id)||await db.Set<OrganizationMember>().AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<MembershipRepresentative>().AnyAsync(o=>o.MembershipId==m.Id)||await db.Assignments.AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<MembershipRenewal>().AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<FinanceInvoice>().AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<Credential>().AnyAsync(o=>o.MembershipId==m.Id)||await db.MemberDocuments.AnyAsync(o=>o.MembershipId==m.Id)||await db.MembershipTransfers.AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<EventRegistration>().AnyAsync(o=>o.MembershipId==m.Id)||await db.Set<VolunteerAttendance>().AnyAsync(o=>o.MembershipId==m.Id);if(linked)throw new DomainException("This holder has linked identity or organization history. Create a separate membership of the correct kind; linked people and organizations cannot be merged by reclassification.");person=new Person();db.Persons.Add(person);m.PersonId=person.Id;reclassified=true;profile=new JsonObject{["email"]=profile["email"]?.DeepClone(),["phone"]=profile["phone"]?.DeepClone(),["city"]=profile["city"]?.DeepClone(),["addresses"]=profile["addresses"]?.DeepClone()};}
   if(m.Status=="Active"&&(r.Status!="Active"||m.ChapterId!=r.ChapterId))await s.RevokeOfficers(m,a.UserId);
   if(m.ChapterId!=r.ChapterId&&await db.MembershipTransfers.AnyAsync(t=>t.MembershipId==m.Id&&t.AppliedAt==null&&t.Status!="Rejected"&&t.Status!="Cancelled"))throw new DomainException("Resolve the pending chapter transfer before changing chapter manually");
  }
  person.FullName=r.FullName.Trim();person.SearchName=person.FullName.ToLowerInvariant();person.Revision++;
  if(category.Kind!="Individual")profile["organizationName"]=person.FullName;
  m.Number=number;m.CategoryId=r.CategoryId;m.ChapterId=r.ChapterId;m.Status=r.Status;m.JoinedAt=id!=null&&Date(m.JoinedAt)==r.JoinedOn?m.JoinedAt:Start(r.JoinedOn);m.EffectiveFrom=id!=null&&Date(m.EffectiveFrom)==r.ValidFrom?m.EffectiveFrom:Start(r.ValidFrom);m.EndsAt=r.ValidThrough==null?null:(id!=null&&m.EndsAt!=null&&Date(m.EndsAt.Value.AddTicks(-1))==r.ValidThrough?m.EndsAt:Start(r.ValidThrough.Value.AddDays(1)));if(m.EndsAt<=m.EffectiveFrom)throw new DomainException("Expiry must follow the effective start");if(r.Status=="Active")m.PendingPayment=false;m.Profile=profile.ToJsonString();MembershipService.ValidateProfile(m.Profile);m.Revision++;
  if(category.Kind!="Individual"){var links=await db.Set<InstitutionChapter>().Where(l=>l.TenantId==tenant&&l.MembershipId==m.Id).Select(l=>l.ChapterId).ToArrayAsync();foreach(var u in await db.Units.Where(u=>u.TenantId==tenant&&links.Contains(u.Id)).ToListAsync()){var d=MembershipService.Json(u.Details);foreach(var key in new[]{"contacts","contactName","contactEmail","contactPhone"})if(profile[key]!=null)d[key]=profile[key]!.DeepClone();u.Details=d.ToJsonString();u.Revision++;u.UpdatedAt=DateTimeOffset.UtcNow;}}
  foreach(var ap in await db.OfficerAppointments.Where(ap=>ap.MembershipId==m.Id&&ap.Status=="Approved"&&m.EndsAt!=null&&ap.EndsAt>m.EndsAt).ToListAsync()){ap.EndsAt=m.EndsAt!.Value;ap.Revision++;if(ap.AssignmentId!=null){var grant=await db.Assignments.FindAsync(ap.AssignmentId);if(grant!=null)grant.EndsAt=m.EndsAt;}}
  foreach(var grant in await(from g in db.Assignments join role in db.GovernanceRoles on g.RoleId equals role.Id where g.MembershipId==m.Id&&role.Name=="Member Directory" select g).ToListAsync())grant.UnitId=m.ChapterId;await s.SyncDirectoryTerm(m);s.History(m,a.UserId,id==null?"platform.membership.created":"platform.membership.updated",new{reason=r.Reason,before,after=Snapshot(m,person),manualEntitlement=r.Status=="Active",reclassified,billing="Unchanged"});if(id==null&&r.AllowEmailClaim&&category.Kind=="Individual"){var claim=profile["email"]?.ToString().Trim();if(string.IsNullOrWhiteSpace(claim)||!System.Net.Mail.MailAddress.TryCreate(claim,out _))throw new DomainException("Enter a valid personal email for membership account access");s.History(m,a.UserId,"membership.manual.claim.approved",new{claimEmails=new[]{claim.ToUpperInvariant()},reason=r.Reason});}await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{m.Id,m.Number,kind=category.Kind,m.Revision});
 }
}
